// pages/workspace/[id]/interview/[candidateId].tsx
// Interview page for a candidate within a workspace.
// Shows interview questions fetched from the interview API, allows the interviewer to type an answer,
// submits the answer for analysis, and displays any follow‑up generated by the orchestrator.

import { useEffect, useState } from 'react';
import { useRouter } from 'next/router';

export default function InterviewPage() {
  const router = useRouter();
  const { id: workspaceId, candidateId } = router.query as {
    id?: string;
    candidateId?: string;
  };

  const [questions, setQuestions] = useState<string[]>([]);
  const [currentIdx, setCurrentIdx] = useState(0);
  const [answer, setAnswer] = useState('');
  const [analysis, setAnalysis] = useState<any>(null);
  const [followUp, setFollowUp] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Load interview questions when the component mounts.
  useEffect(() => {
    // The GET endpoint ignores query parameters; we call it directly.
    fetch('/api/interview')
      .then((res) => res.json())
      .then((data) => {
        setQuestions(data.questions ?? []);
        setCurrentIdx(0);
      })
      .catch((err) => {
        console.error(err);
        setError('Failed to load interview questions');
      });
  }, []);

  const handleSubmit = async () => {
    if (!questions[currentIdx]) return;
    setLoading(true);
    setError(null);
    try {
      const payload = {
        response: answer,
        // The orchestrator currently expects an interviewPlan object; we provide an empty placeholder.
        interviewPlan: {},
      };
      const res = await fetch('/api/interview', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || 'Submission failed');
      }
      const data = await res.json();
      setAnalysis(data.analysis);
      setFollowUp(data.followUp);
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  const currentQuestion = questions[currentIdx];

  return (
    <div className="p-6 max-w-3xl mx-auto">
      {/* Navigation back */}
      <nav className="mb-4">
        <button
          onClick={() => router.back()}
          className="text-blue-600 hover:underline"
        >
          ← Back
        </button>
      </nav>

      {error && <p className="text-red-600 mb-4">Error: {error}</p>}

      {currentQuestion ? (
        <section>
          <h2 className="text-xl font-semibold mb-2">Interview Question</h2>
          <p className="mb-4">{currentQuestion}</p>

          <textarea
            className="w-full h-32 p-2 border rounded mb-4"
            placeholder="Type your answer here..."
            value={answer}
            onChange={(e) => setAnswer(e.target.value)}
            disabled={loading}
          />

          <button
            className="px-4 py-2 bg-blue-600 text-white rounded disabled:opacity-50"
            onClick={handleSubmit}
            disabled={loading || !answer.trim()}
          >
            Submit Answer
          </button>

          {analysis && (
            <div className="mt-6 p-4 bg-gray-100 rounded">
              <h3 className="font-semibold mb-2">Analysis</h3>
              <pre className="whitespace-pre-wrap text-sm">
                {JSON.stringify(analysis, null, 2)}
              </pre>
            </div>
          )}

          {followUp && (
            <div className="mt-6 p-4 bg-yellow-100 rounded">
              <h3 className="font-semibold mb-2">Follow‑up</h3>
              <pre className="whitespace-pre-wrap text-sm">
                {JSON.stringify(followUp, null, 2)}
              </pre>
            </div>
          )}
        </section>
      ) : (
        !error && <p>Loading interview questions...</p>
      )}
    </div>
  );
}
